111|size_t
112|png_safecat(png_charp buffer, size_t bufsize, size_t pos,
113|    png_const_charp string)
114|{
115|   if (buffer != NULL && pos < bufsize)
116|   {
117|      if (string != NULL)
118|         while (*string != '\0' && pos < bufsize-1)
119|           buffer[pos++] = *string++;
120|
121|      buffer[pos] = '\0';
122|   }
123|
124|   return pos;
